package legacy.account;

public class LegacyAccount {
    private String accountNumber;
    private String customerId;
    private String customerName;
    private String accountType;
    private double balance;
    private String status;
    private int failedAttempts;
    private boolean kycVerified;
    private String riskCategory;

    public LegacyAccount(String accountNumber, String customerId, String customerName,
                         String accountType, double balance) {
        this.accountNumber = accountNumber;
        this.customerId = customerId;
        this.customerName = customerName;
        this.accountType = accountType;
        this.balance = balance;
        this.status = "ACTIVE";
        this.failedAttempts = 0;
        this.kycVerified = false;
        this.riskCategory = "NORMAL";
    }

    public String getAccountNumber() { return accountNumber; }
    public String getCustomerId() { return customerId; }
    public String getCustomerName() { return customerName; }
    public String getAccountType() { return accountType; }
    public double getBalance() { return balance; }
    public String getStatus() { return status; }
    public int getFailedAttempts() { return failedAttempts; }
    public boolean isKycVerified() { return kycVerified; }
    public String getRiskCategory() { return riskCategory; }

    public void setStatus(String status) { this.status = status; }
    public void setKycVerified(boolean value) { this.kycVerified = value; }
    public void setRiskCategory(String category) { this.riskCategory = category; }

    public void increaseFailedAttempts() {
        failedAttempts = failedAttempts + 1;
    }

    public void resetFailedAttempts() {
        failedAttempts = 0;
    }

    public boolean debit(double amount) {
        if (amount <= 0) {
            return false;
        }

        if ("BLOCKED".equals(status) || "CLOSED".equals(status)) {
            return false;
        }

        if ("SAVINGS".equals(accountType) && amount > balance) {
            return false;
        }

        if ("CURRENT".equals(accountType) && amount > balance + 10000) {
            return false;
        }

        balance = balance - amount;
        return true;
    }

    public boolean credit(double amount) {
        if (amount <= 0 || "CLOSED".equals(status)) {
            return false;
        }

        balance = balance + amount;
        return true;
    }

    public boolean canTransact() {
        if (!"ACTIVE".equals(status)) {
            return false;
        }

        if (!kycVerified) {
            return false;
        }

        return true;
    }

    public String toString() {
        return accountNumber + "|" + customerId + "|" + customerName + "|"
                + accountType + "|" + balance + "|" + status + "|" + riskCategory;
    }
}

package legacy.account;

import java.util.ArrayList;
import java.util.List;

public class LegacyAccountProcessor {
    private static final double SAVINGS_MIN_BALANCE = 1000.00;
    private static final double PREMIUM_THRESHOLD = 500000.00;
    private static final double HIGH_RISK_THRESHOLD = 1000000.00;
    private static final int MAX_LOGIN_FAILURES = 3;

    private List<LegacyAccount> accounts;

    public LegacyAccountProcessor() {
        accounts = new ArrayList<LegacyAccount>();
    }

    public void addAccount(LegacyAccount account) {
        if (account == null) {
            return;
        }

        if (findAccount(account.getAccountNumber()) != null) {
            System.out.println("Duplicate account rejected");
            return;
        }

        accounts.add(account);
        System.out.println("Account added: " + account.getAccountNumber());
    }

    public LegacyAccount findAccount(String accountNumber) {
        if (accountNumber == null) {
            return null;
        }

        for (LegacyAccount account : accounts) {
            if (accountNumber.equals(account.getAccountNumber())) {
                return account;
            }
        }

        return null;
    }

    public boolean verifyKyc(String accountNumber, String documentType,
                             String documentNumber) {
        LegacyAccount account = findAccount(accountNumber);

        if (account == null) {
            return false;
        }

        if (documentNumber == null || documentNumber.trim().length() < 6) {
            return false;
        }

        if (!"PAN".equals(documentType) && !"PASSPORT".equals(documentType)
                && !"AADHAAR".equals(documentType)) {
            return false;
        }

        account.setKycVerified(true);
        account.resetFailedAttempts();
        return true;
    }

    public boolean authenticate(String accountNumber, String pin) {
        LegacyAccount account = findAccount(accountNumber);

        if (account == null || pin == null) {
            return false;
        }

        if ("BLOCKED".equals(account.getStatus())) {
            return false;
        }

        if (pin.length() != 4) {
            account.increaseFailedAttempts();
            applyFailureRule(account);
            return false;
        }

        if ("0000".equals(pin)) {
            account.increaseFailedAttempts();
            applyFailureRule(account);
            return false;
        }

        account.resetFailedAttempts();
        return true;
    }

    private void applyFailureRule(LegacyAccount account) {
        if (account.getFailedAttempts() >= MAX_LOGIN_FAILURES) {
            account.setStatus("BLOCKED");
            System.out.println("Account blocked after repeated failures");
        }
    }

    public String processWithdrawal(String accountNumber, double amount) {
        LegacyAccount account = findAccount(accountNumber);

        if (account == null) {
            return "ACCOUNT_NOT_FOUND";
        }

        if (!account.canTransact()) {
            return "TRANSACTION_NOT_ALLOWED";
        }

        if (amount <= 0) {
            return "INVALID_AMOUNT";
        }

        double fee = calculateWithdrawalFee(account, amount);
        double total = amount + fee;

        if ("SAVINGS".equals(account.getAccountType())
                && account.getBalance() - total < SAVINGS_MIN_BALANCE) {
            return "MINIMUM_BALANCE_VIOLATION";
        }

        if (!account.debit(total)) {
            return "INSUFFICIENT_FUNDS";
        }

        updateRisk(account, total);
        return "SUCCESS|FEE=" + fee + "|BALANCE=" + account.getBalance();
    }

    public String processDeposit(String accountNumber, double amount) {
        LegacyAccount account = findAccount(accountNumber);

        if (account == null) {
            return "ACCOUNT_NOT_FOUND";
        }

        if (!account.canTransact()) {
            return "TRANSACTION_NOT_ALLOWED";
        }

        if (amount <= 0) {
            return "INVALID_AMOUNT";
        }

        double fee = 0.0;

        if (amount > 100000) {
            fee = 50.0;
        }

        if (!account.credit(amount - fee)) {
            return "DEPOSIT_FAILED";
        }

        updateRisk(account, amount);
        return "SUCCESS|FEE=" + fee + "|BALANCE=" + account.getBalance();
    }

    private double calculateWithdrawalFee(LegacyAccount account, double amount) {
        double fee = 0.0;

        if ("SAVINGS".equals(account.getAccountType())) {
            if (amount <= 10000) {
                fee = 10.0;
            } else if (amount <= 50000) {
                fee = 25.0;
            } else {
                fee = 50.0;
            }
        } else if ("CURRENT".equals(account.getAccountType())) {
            if (amount <= 50000) {
                fee = 15.0;
            } else {
                fee = 30.0;
            }
        }

        if ("PREMIUM".equals(account.getRiskCategory())) {
            fee = fee * 0.50;
        }

        return fee;
    }

    private void updateRisk(LegacyAccount account, double transactionAmount) {
        if (transactionAmount >= HIGH_RISK_THRESHOLD) {
            account.setRiskCategory("HIGH");
        } else if (account.getBalance() >= PREMIUM_THRESHOLD) {
            account.setRiskCategory("PREMIUM");
        } else if (transactionAmount >= 250000) {
            account.setRiskCategory("REVIEW");
        } else {
            account.setRiskCategory("NORMAL");
        }
    }

    public boolean closeAccount(String accountNumber) {
        LegacyAccount account = findAccount(accountNumber);

        if (account == null) {
            return false;
        }

        if (account.getBalance() != 0) {
            return false;
        }

        if (!"ACTIVE".equals(account.getStatus())) {
            return false;
        }

        account.setStatus("CLOSED");
        return true;
    }

    public List<LegacyAccount> getAccountsByRisk(String risk) {
        List<LegacyAccount> result = new ArrayList<LegacyAccount>();

        for (LegacyAccount account : accounts) {
            if (risk != null && risk.equals(account.getRiskCategory())) {
                result.add(account);
            }
        }

        return result;
    }

    public double calculateTotalBalance() {
        double total = 0.0;

        for (LegacyAccount account : accounts) {
            if (!"CLOSED".equals(account.getStatus())) {
                total = total + account.getBalance();
            }
        }

        return total;
    }

    public void printAccountSummary() {
        System.out.println("----- ACCOUNT SUMMARY -----");

        for (LegacyAccount account : accounts) {
            System.out.println(account.toString());

            if (account.getBalance() > PREMIUM_THRESHOLD) {
                System.out.println("Customer qualifies for premium review");
            }

            if (!account.isKycVerified()) {
                System.out.println("KYC pending");
            }

            if ("BLOCKED".equals(account.getStatus())) {
                System.out.println("Manual unblock required");
            }
        }

        System.out.println("Total Balance: " + calculateTotalBalance());
    }
}

package legacy.account;

import java.util.ArrayList;
import java.util.List;

public class LegacyTransactionProcessor {
    private List<String> transactionHistory;
    private int transactionCounter;

    public LegacyTransactionProcessor() {
        transactionHistory = new ArrayList<String>();
        transactionCounter = 1000;
    }

    public String transfer(LegacyAccountProcessor processor,
                           String fromAccount,
                           String toAccount,
                           double amount) {
        LegacyAccount source = processor.findAccount(fromAccount);
        LegacyAccount target = processor.findAccount(toAccount);

        if (source == null || target == null) {
            return "ACCOUNT_NOT_FOUND";
        }

        if (fromAccount.equals(toAccount)) {
            return "SAME_ACCOUNT_TRANSFER";
        }

        if (!source.canTransact() || !target.canTransact()) {
            return "TRANSACTION_NOT_ALLOWED";
        }

        if (amount <= 0) {
            return "INVALID_AMOUNT";
        }

        if (amount > 500000) {
            return "TRANSFER_LIMIT_EXCEEDED";
        }

        double fee = calculateTransferFee(source, target, amount);

        if (!source.debit(amount + fee)) {
            return "INSUFFICIENT_FUNDS";
        }

        if (!target.credit(amount)) {
            source.credit(amount + fee);
            return "CREDIT_FAILED";
        }

        String transactionId = "TX" + transactionCounter;
        transactionCounter++;

        transactionHistory.add(transactionId + "|" + fromAccount + "|"
                + toAccount + "|" + amount + "|" + fee + "|SUCCESS");

        return "SUCCESS|" + transactionId + "|FEE=" + fee;
    }

    private double calculateTransferFee(LegacyAccount source,
                                        LegacyAccount target,
                                        double amount) {
        double fee;

        if (source.getCustomerId().equals(target.getCustomerId())) {
            fee = 0.0;
        } else if (amount <= 10000) {
            fee = 5.0;
        } else if (amount <= 100000) {
            fee = 15.0;
        } else {
            fee = 30.0;
        }

        if ("PREMIUM".equals(source.getRiskCategory())) {
            fee = fee * 0.25;
        }

        return fee;
    }

    public String reverseLastTransaction() {
        if (transactionHistory.size() == 0) {
            return "NO_TRANSACTION";
        }

        String last = transactionHistory.get(transactionHistory.size() - 1);
        String[] data = last.split("\\|");

        if (data.length < 6) {
            return "INVALID_TRANSACTION_RECORD";
        }

        if ("REVERSED".equals(data[5])) {
            return "ALREADY_REVERSED";
        }

        String updated = data[0] + "|" + data[1] + "|" + data[2] + "|"
                + data[3] + "|" + data[4] + "|REVERSED";

        transactionHistory.set(transactionHistory.size() - 1, updated);
        return "REVERSAL_MARKED";
    }

    public void printTransactionHistory() {
        System.out.println("----- TRANSACTION HISTORY -----");

        if (transactionHistory.size() == 0) {
            System.out.println("No transactions available");
            return;
        }

        for (String transaction : transactionHistory) {
            System.out.println(transaction);
        }
    }

    public int getTransactionCount() {
        return transactionHistory.size();
    }
}

